  "tech2.hw.desc": { pt: "Começamos com identificação RFID/NFC já aprovada e um registo simples na app. Colares GPS e eartags eletrónicos entram depois, quando o caso de uso justificar mais autonomia e engenharia.", en: "We start with an approved RFID/NFC identifier and a simple record in the app. GPS collars and electronic ear tags come later, when the use case justifies more autonomy and engineering.", es: "Empezamos con identificación RFID/NFC ya aprobada y un registro sencillo en la app. Los collares GPS y aretes electrónicos llegan después, cuando el caso de uso justifica más autonomía e ingeniería." },
  "tech2.hw.collar.name": { pt: "Evolução do rastreio animal", en: "The evolution of animal tracking", es: "Evolución del rastreo animal" },
  "tech2.hw.collar.cat": { pt: "RFID/NFC → Colar GPS → Smart Eartag", en: "RFID/NFC → GPS Collar → Smart Ear Tag", es: "RFID/NFC → Collar GPS → Arete inteligente" },
  "tech2.hw.collar.desc": { pt: "A primeira versão liga um eartag RFID/NFC adquirido a uma ficha digital do animal. O passo seguinte acrescenta localização e movimento através de um colar GPS. Um smart eartag miniaturizado fica como evolução, depois de validar autonomia, resistência e valor real no terreno.", en: "The first version links a purchased RFID/NFC ear tag to the animal's digital record. The next step adds location and movement through a GPS collar. A miniaturised smart ear tag follows only after battery life, durability and real field value are proven.", es: "La primera versión vincula un arete RFID/NFC adquirido a la ficha digital del animal. El siguiente paso añade ubicación y movimiento mediante un collar GPS. Un arete inteligente miniaturizado llega solo después de validar autonomía, resistencia y valor real en campo." },
  "tech2.hw.footnote": { pt: "A GeoVision complementa a identificação oficial do animal; não a substitui. Cada fase é validada no terreno antes de aumentar a complexidade do hardware.", en: "GeoVision complements the animal's official identification; it does not replace it. Each phase is field-tested before hardware complexity increases.", es: "GeoVision complementa la identificación oficial del animal; no la sustituye. Cada fase se valida en campo antes de aumentar la complejidad del hardware." },
  "tech2.tag.tx4g": { pt: "Transmissão 4G", en: "4G Transmission", es: "Transmisión 4G" },
  "tech2.tag.autoAlerts": { pt: "Alertas Automáticos", en: "Automatic Alerts", es: "Alertas Automáticas" },
  "tech2.tag.animalBehaviour": { pt: "Comportamento Animal", en: "Animal Behaviour", es: "Comportamiento Animal" },
  "tech2.inputs.eyebrow": { pt: "Execução de Campo", en: "Field Execution", es: "Ejecución de Campo" },
  "tech2.inputs.title": { pt: "Insumos Agrícolas & Dispersão Aérea", en: "Agricultural Inputs & Aerial Spreading", es: "Insumos Agrícolas y Dispersión Aérea" },
  "tech2.inputs.desc": { pt: "A frota DJI Agras T40 permite aplicação de taxa variável e dispersão de materiais sólidos com precisão prescritiva — integrando insumos agrícolas diretamente no pipeline de execução GeoVision.", en: "The DJI Agras T40 fleet enables variable-rate application and solid-material spreading with prescriptive precision — integrating agricultural inputs directly into the GeoVision execution pipeline.", es: "La flota DJI Agras T40 permite la aplicación de tasa variable y la dispersión de materiales sólidos con precisión prescriptiva, integrando insumos agrícolas directamente en el pipeline de ejecución GeoVision." },
  "tech2.inputs.phyto.name": { pt: "Produtos Fitossanitários", en: "Crop Protection Products", es: "Productos Fitosanitarios" },
  "tech2.inputs.phyto.cat": { pt: "Pulverização Variável", en: "Variable-Rate Spraying", es: "Pulverización Variable" },
  "tech2.inputs.phyto.desc": { pt: "Herbicidas, fungicidas, inseticidas e bioestimulantes aplicados via T40 com prescrição por zona baseada em mapas NDVI. Dosagem calculada em L/ha conforme regras agronómicas do cliente.", en: "Herbicides, fungicides, insecticides and biostimulants applied via the T40 with zone-based prescription from NDVI maps. Dosage calculated in L/ha per the client's agronomic rules.", es: "Herbicidas, fungicidas, insecticidas y bioestimulantes aplicados con el T40 con prescripción por zona basada en mapas NDVI. Dosis calculada en L/ha según las reglas agronómicas del cliente." },
  "tech2.inputs.seeds.name": { pt: "Sementes & Fertilizantes", en: "Seeds & Fertilizers", es: "Semillas y Fertilizantes" },
  "tech2.inputs.seeds.cat": { pt: "Dispersão Sólida — até 50 kg", en: "Solid Spreading — up to 50 kg", es: "Dispersión Sólida — hasta 50 kg" },
  "tech2.inputs.seeds.desc": { pt: "Dispersão aérea de sementes (reflorestação, cobertura vegetal, pastagens) e fertilizantes granulados com o T40. Distribuição controlada por zona com dosagem em kg/ha conforme prescrição agronómica.", en: "Aerial spreading of seeds (reforestation, ground cover, pasture) and granular fertilizers with the T40. Zone-controlled distribution with dosage in kg/ha per agronomic prescription.", es: "Dispersión aérea de semillas (reforestación, cobertura vegetal, pastos) y fertilizantes granulados con el T40. Distribución controlada por zona con dosis en kg/ha según prescripción agronómica." },
  "tech2.inputs.footnote": { pt: "Os insumos são fornecidos pelo cliente ou adquiridos através do GeoVision Supply Hub. A GeoVision executa a aplicação conforme prescrição — a seleção de produtos e dosagens é responsabilidade do engenheiro agrónomo do cliente.", en: "Inputs are supplied by the client or purchased through the GeoVision Supply Hub. GeoVision performs the application per prescription — product and dosage selection is the responsibility of the client's agronomist.", es: "Los insumos son suministrados por el cliente o adquiridos a través del GeoVision Supply Hub. GeoVision ejecuta la aplicación según prescripción — la selección de productos y dosis es responsabilidad del agrónomo del cliente." },
