  // ---- Technology page: IoT & Sensor platform section ----
  "iot3.eyebrow": { pt: "Monitorização em Tempo Real", en: "Real-Time Monitoring", es: "Monitoreo en Tiempo Real" },
  "iot3.title": { pt: "Plataforma IoT & Sensores", en: "IoT & Sensor Platform", es: "Plataforma IoT y Sensores" },
  "iot3.desc": { pt: "Dispositivos GeoVision baseados em ESP32 transmitem telemetria por MQTT/TLS ou REST para o painel — dados ao vivo, alertas por limiar, relatórios analíticos e controlo seguro de baixa tensão. Nós montamos o dispositivo; o cliente instala, provisiona e vê os dados em minutos.", en: "GeoVision's ESP32-based devices stream telemetry over MQTT/TLS or REST to the dashboard — live data, threshold alerts, analytical reports and safe low-voltage control. We assemble the device; the customer installs, provisions and sees data in minutes.", es: "Los dispositivos GeoVision basados en ESP32 transmiten telemetría por MQTT/TLS o REST al panel — datos en vivo, alertas por umbral, informes analíticos y control seguro de baja tensión. Nosotros montamos el dispositivo; el cliente lo instala, aprovisiona y ve los datos en minutos." },
  "iot3.kits.name": { pt: "Kits de Sensores Prontos", en: "Ready Sensor Kits", es: "Kits de Sensores Listos" },
  "iot3.kits.cat": { pt: "Monitorização por Setor", en: "Monitoring by Sector", es: "Monitoreo por Sector" },
  "iot3.kits.desc": { pt: "Kits GeoVision pré-configurados para cadeia de frio, tanques e bombas de água, energia, campo agrícola (solar), instalações e qualidade do ar — cada um com os sensores, canais e alertas certos, prontos a provisionar.", en: "Pre-configured GeoVision kits for cold chain, water tanks and pumps, energy, solar farm field, facilities and air quality — each with the right sensors, channels and alerts, ready to provision.", es: "Kits GeoVision preconfigurados para cadena de frío, tanques y bombas de agua, energía, campo agrícola (solar), instalaciones y calidad del aire — cada uno con los sensores, canales y alertas correctos, listos para aprovisionar." },
  "iot3.tag.coldChain": { pt: "Cadeia de Frio", en: "Cold Chain", es: "Cadena de Frío" },
  "iot3.tag.waterTank": { pt: "Água & Tanques", en: "Water & Tanks", es: "Agua y Tanques" },
  "iot3.tag.energy": { pt: "Energia", en: "Energy", es: "Energía" },
  "iot3.tag.agriField": { pt: "Campo Agrícola", en: "Farm Field", es: "Campo Agrícola" },
  "iot3.tag.facility": { pt: "Instalações", en: "Facilities", es: "Instalaciones" },
  "iot3.tag.airQuality": { pt: "Qualidade do Ar", en: "Air Quality", es: "Calidad del Aire" },
  "iot3.telemetry.name": { pt: "Telemetria & Painel ao Vivo", en: "Telemetry & Live Dashboard", es: "Telemetría y Panel en Vivo" },
  "iot3.telemetry.cat": { pt: "ESP32 · MQTT/TLS · REST", en: "ESP32 · MQTT/TLS · REST", es: "ESP32 · MQTT/TLS · REST" },
  "iot3.telemetry.desc": { pt: "Provisionamento seguro por token único, ingestão assinada por MQTT/TLS ou REST, atualizações ao vivo no painel (SSE/WebSocket) e localização no mapa com abertura direta no Google Maps.", en: "Secure one-time-token provisioning, signed ingestion over MQTT/TLS or REST, live dashboard updates (SSE/WebSocket) and map location with direct Google Maps open.", es: "Aprovisionamiento seguro por token único, ingesta firmada por MQTT/TLS o REST, actualizaciones en vivo en el panel (SSE/WebSocket) y ubicación en el mapa con apertura directa en Google Maps." },
  "iot3.tag.secureProvisioning": { pt: "Provisionamento Seguro", en: "Secure Provisioning", es: "Aprovisionamiento Seguro" },
  "iot3.tag.liveDashboard": { pt: "Painel ao Vivo", en: "Live Dashboard", es: "Panel en Vivo" },
  "iot3.tag.mapGps": { pt: "Mapa & GPS", en: "Map & GPS", es: "Mapa y GPS" },
  "iot3.alerts.name": { pt: "Alertas & Relatórios Analíticos", en: "Alerts & Analytical Reports", es: "Alertas e Informes Analíticos" },
  "iot3.alerts.cat": { pt: "Decisão com Dados", en: "Data-Driven Decisions", es: "Decisiones con Datos" },
  "iot3.alerts.desc": { pt: "Regras de alerta por limiar, offline, bateria fraca ou variação rápida, com ciclo de vida completo (disparo → notificação → resolução). KPIs, tempo-em-limite, horas de funcionamento e relatórios em PDF/CSV.", en: "Alert rules for threshold, offline, low battery or rapid change, with a full lifecycle (triggered → notified → resolved). KPIs, time-in-range, run-hours and PDF/CSV reports.", es: "Reglas de alerta por umbral, sin conexión, batería baja o variación rápida, con ciclo de vida completo (disparo → notificación → resolución). KPIs, tiempo-en-rango, horas de funcionamiento e informes PDF/CSV." },
  "iot3.tag.thresholdAlerts": { pt: "Alertas por Limiar", en: "Threshold Alerts", es: "Alertas por Umbral" },
  "iot3.tag.pdfCsvReports": { pt: "Relatórios PDF/CSV", en: "PDF/CSV Reports", es: "Informes PDF/CSV" },
  "iot3.tag.safeControl": { pt: "Controlo Seguro", en: "Safe Control", es: "Control Seguro" },
  "iot3.sensors.name": { pt: "Sensores Suportados", en: "Supported Sensors", es: "Sensores Soportados" },
  "iot3.sensors.cat": { pt: "Modelo Extensível", en: "Extensible Model", es: "Modelo Extensible" },
  "iot3.sensors.desc": { pt: "Temperatura, humidade, humidade e temperatura do solo, nível de tanque, caudal, tensão/corrente/potência/energia, fuga de água, porta/movimento, CO₂, PM2.5, ruído, GPS, vibração, bateria e sinal — com unidades validadas e novos tipos adicionáveis.", en: "Temperature, humidity, soil moisture and temperature, tank level, flow, voltage/current/power/energy, water leak, door/motion, CO₂, PM2.5, noise, GPS, vibration, battery and signal — with validated units and new types easily added.", es: "Temperatura, humedad, humedad y temperatura del suelo, nivel de tanque, caudal, tensión/corriente/potencia/energía, fuga de agua, puerta/movimiento, CO₂, PM2.5, ruido, GPS, vibración, batería y señal — con unidades validadas y nuevos tipos fáciles de añadir." },
  "iot3.tag.tempHumidity": { pt: "Temperatura & Humidade", en: "Temperature & Humidity", es: "Temperatura y Humedad" },
  "iot3.tag.soil": { pt: "Solo", en: "Soil", es: "Suelo" },
  "iot3.tag.levelFlow": { pt: "Nível & Caudal", en: "Level & Flow", es: "Nivel y Caudal" },
  "iot3.tag.vibration": { pt: "Vibração", en: "Vibration", es: "Vibración" },

