  "index.entry.farm.name": { pt: "Terra & Culturas", en: "Farm & Land", es: "Tierra & Cultivos" },
  "index.entry.farm.desc": { pt: "Acompanhe solo, água, clima e culturas.", en: "Monitor soil, water, weather and crops.", es: "Monitorice suelo, agua, clima y cultivos." },
