  "about.sector.mining.name": { pt: "Inteligência de Operações Mineiras", en: "Mining Operations Intelligence", es: "Inteligencia de Operaciones Mineras" },
  "about.sector.mining.desc": { pt: "Mapeamento topográfico 3D, análise volumétrica, monitorização de estabilidade de taludes e inteligência abrangente de minas.", en: "3D topographic mapping, volumetric analysis, slope stability monitoring and comprehensive mine site intelligence.", es: "Mapeo topográfico 3D, análisis volumétrico, monitoreo de estabilidad de taludes e inteligencia integral de minas." },
