  "about.sector.agri.desc": { pt: "Análise de saúde de culturas NDVI, pulverização de precisão, contagem de gado e gestão de terras.", en: "NDVI crop health analysis, precision spraying, livestock counting and land management.", es: "Análisis de salud de cultivos NDVI, pulverización de precisión, conteo de ganado y gestión de tierras." },
  "about.sector.demining.name": { pt: "Desminagem e Segurança Territorial", en: "Demining & Territorial Safety", es: "Desminado y Seguridad Territorial" },
  "about.sector.demining.desc": { pt: "Mapeamento térmico, deteção de anomalias e suporte operacional para programas humanitários de desminagem.", en: "Thermal mapping, anomaly detection and operational support for humanitarian demining programs.", es: "Mapeo térmico, detección de anomalías y apoyo operacional para programas humanitarios de desminado." },
  "about.sector.solar.name": { pt: "Inspeção Solar e Energia", en: "Solar & Energy Inspection", es: "Inspección Solar y Energía" },
  "about.sector.solar.desc": { pt: "Inspeção térmica de painéis, monitorização de parques solares e avaliação de infraestrutura energética.", en: "Thermal panel inspection, solar farm monitoring and energy infrastructure assessment.", es: "Inspección térmica de paneles, monitoreo de parques solares y evaluación de infraestructura energética." },

  // ============ ABOUT PAGE - HYBRID MODEL ============
  "about.hybrid.eyebrow2": { pt: "A Nossa Abordagem", en: "Our Approach", es: "Nuestro Enfoque" },
  "about.hybrid.title2": { pt: "O Nosso Modelo Híbrido", en: "Our Hybrid Model", es: "Nuestro Modelo Híbrido" },
  "about.hybrid.desc": { pt: "Ao contrário dos prestadores de serviços tradicionais, a GeoVision integra análise, monitorização e execução seletiva num framework operacional unificado.", en: "Unlike traditional service providers, GeoVision integrates analysis, monitoring and selective execution into a unified operational framework.", es: "A diferencia de los proveedores de servicios tradicionales, GeoVision integra análisis, monitoreo y ejecución selectiva en un marco operacional unificado." },
  "about.hybrid.frameworkTitle": { pt: "Framework Operacional de Três Níveis", en: "Three-Level Operational Framework", es: "Marco Operacional de Tres Niveles" },
  "about.hybrid.frameworkDesc": { pt: "O nosso modelo híbrido garante que a inteligência se traduz diretamente em resultados operacionais. Não entregamos apenas dados — entregamos resultados.", en: "Our hybrid model ensures that intelligence translates directly into operational outcomes. We don't just deliver data — we deliver results.", es: "Nuestro modelo híbrido garantiza que la inteligencia se traduce directamente en resultados operacionales. No solo entregamos datos — entregamos resultados." },
  "about.hybrid.level1.title": { pt: "Aquisição de Dados", en: "Data Acquisition", es: "Adquisición de Datos" },
  "about.hybrid.level1.desc": { pt: "Plataformas de drone avançadas, sensores multiespectrais e tecnologia LiDAR.", en: "Advanced drone platforms, multispectral sensors and LiDAR technology.", es: "Plataformas de drones avanzadas, sensores multiespectrales y tecnología LiDAR." },
  "about.hybrid.level2.title": { pt: "Inteligência Analítica", en: "Analytical Intelligence", es: "Inteligencia Analítica" },
  "about.hybrid.level2.desc": { pt: "Processamento baseado em IA, integração GIS e modelação de risco estruturada.", en: "AI-powered processing, GIS integration and structured risk modeling.", es: "Procesamiento basado en IA, integración GIS y modelado de riesgos estructurado." },
  "about.hybrid.level3.title": { pt: "Execução Seletiva em Campo", en: "Selective Field Execution", es: "Ejecución Selectiva en Campo" },
  "about.hybrid.level3.desc": { pt: "Equipas no terreno para projetos de alta criticidade que requerem intervenção direta.", en: "On-ground teams for high-criticality projects requiring direct intervention.", es: "Equipos en terreno para proyectos de alta criticidad que requieren intervención directa." },
  "about.hybrid.visualTitle": { pt: "Capacidades Integradas", en: "Integrated Capabilities", es: "Capacidades Integradas" },
