  "index.feature.field.desc": { pt: "Drones DJI (Matrice 350 RTK, Mavic 3M, Agras T40), sensores multiespectrais, sistemas RTK e dispositivos GPS 4G para rastreio pecuário.", en: "DJI drones (Matrice 350 RTK, Mavic 3M, Agras T40), multispectral sensors, RTK systems and 4G GPS devices for livestock tracking.", es: "Drones DJI (Matrice 350 RTK, Mavic 3M, Agras T40), sensores multiespectrales, sistemas RTK y dispositivos GPS 4G para rastreo ganadero." },
