  "index.feature.data.desc": { pt: "API Backend, PostgreSQL/PostGIS, armazenamento cloud seguro e integração com QGIS para análise geoespacial estruturada.", en: "Backend API, PostgreSQL/PostGIS, secure cloud storage and QGIS integration for structured geospatial analysis.", es: "API Backend, PostgreSQL/PostGIS, almacenamiento cloud seguro e integración con QGIS para análisis geoespacial estructurado." },
  "index.feature.interface.title": { pt: "Camada de Interface", en: "Interface Layer", es: "Capa de Interfaz" },
  "index.feature.interface.desc": { pt: "Portal Cliente com dashboards KPI setoriais, mapas interativos, visualização 3D e relatórios estruturados (PDF, DOCX, ficheiros 3D).", en: "Client Portal with sector-specific KPI dashboards, interactive maps, 3D visualization and structured reports (PDF, DOCX, 3D files).", es: "Portal Cliente con dashboards KPI sectoriales, mapas interactivos, visualización 3D e informes estructurados (PDF, DOCX, archivos 3D)." },
  "index.feature.rtk.desc": { pt: "Precisão centimétrica (±1–2 cm) via estação base dedicada ou rede NTRIP. Base dedicada recomendada para operações rurais.", en: "Centimeter-level accuracy (±1–2 cm) via dedicated base station or NTRIP network. Dedicated base recommended for rural operations.", es: "Precisión centimétrica (±1–2 cm) vía estación base dedicada o red NTRIP. Base dedicada recomendada para operaciones rurales." },
  "index.sector.agro.desc": { pt: "NDVI multiespectral, mapas de prescrição, pulverização variável, contagem aérea de gado e rastreio GPS 4G com alertas de geofence.", en: "Multispectral NDVI, prescription maps, variable-rate spraying, aerial cattle counting and 4G GPS tracking with geofence alerts.", es: "NDVI multiespectral, mapas de prescripción, pulverización variable, conteo aéreo de ganado y rastreo GPS 4G con alertas de geofence." },
  "index.sector.mineracao.desc": { pt: "Topografia 3D, volumetria comparativa, monitorização de taludes e inteligência de mina.", en: "3D topography, comparative volumetry, slope monitoring and mine intelligence.", es: "Topografía 3D, volumetría comparativa, monitorización de taludes e inteligencia de mina." },
  "index.sector.construcao.desc": { pt: "Acompanhamento de obra, análise volumétrica, documentação as-built e controlo de projeto.", en: "Construction progress tracking, volumetric analysis, as-built documentation and project control.", es: "Seguimiento de obra, análisis volumétrico, documentación as-built y control de proyecto." },
  "index.sector.infraestruturas.desc": { pt: "Estradas, barragens, linhas de transmissão e monitorização de corredores com avaliação de condição.", en: "Roads, dams, transmission lines and corridor monitoring with condition assessment.", es: "Carreteras, presas, líneas de transmisión y monitorización de corredores con evaluación de condición." },

