  "sectors.construcao.eyebrow": { pt: "Construção & Obras", en: "Construction & Works", es: "Construcción y Obras" },
  "sectors.construcao.title": { pt: "Acompanhamento de Obra, Volumetria & As-Built", en: "Construction Tracking, Volumetry & As-Built", es: "Seguimiento de Obra, Volumetría y As-Built" },
  "sectors.construcao.desc": { pt: "A GeoVision documenta o progresso de obra com levantamentos aéreos recorrentes — criando uma linha temporal visual desde a primeira intervenção até à entrega final para empreiteiros, supervisores e donos de obra.", en: "GeoVision documents construction progress with recurring aerial surveys — creating a visual timeline from the first intervention to final delivery for contractors, supervisors and project owners.", es: "GeoVision documenta el progreso de obra con levantamientos aéreos recurrentes — creando una línea temporal visual desde la primera intervención hasta la entrega final para contratistas, supervisores y propietarios de obra." },
