  "sectors.infraestruturas": { pt: "Infraestruturas", en: "Infrastructure", es: "Infraestructuras" },
  "sectors.infraestruturas.title": { pt: "Estradas, Barragens & Corredores Logísticos", en: "Roads, Dams & Logistics Corridors", es: "Carreteras, Presas y Corredores Logísticos" },
  "sectors.infraestruturas.desc": { pt: "A GeoVision fornece \"snapshots\" visuais recorrentes de ativos estratégicos — estradas, barragens, linhas de transmissão, canais de drenagem — suportando planeamento de manutenção e decisões de investimento baseadas em dados reais.", en: "GeoVision provides recurring visual snapshots of strategic assets — roads, dams, transmission lines, drainage channels — supporting maintenance planning and investment decisions based on real data.", es: "GeoVision proporciona \"snapshots\" visuales recurrentes de activos estratégicos — carreteras, presas, líneas de transmisión, canales de drenaje — apoyando la planificación de mantenimiento y decisiones de inversión basadas en datos reales." },
  "sectors.infraestruturas.step1.title": { pt: "Segmentação de Ativos", en: "Asset Segmentation", es: "Segmentación de Activos" },
  "sectors.infraestruturas.step1.desc": { pt: "Divisão de estradas, canais ou linhas em secções standard para comparação de performance e estado.", en: "Division of roads, channels or lines into standard sections for performance and condition comparison.", es: "División de carreteras, canales o líneas en secciones estándar para comparación de rendimiento y estado." },
