// ============ i18n ENGINE ============
class I18n {
  constructor() {
    this.currentLang = localStorage.getItem('gv_lang') || 'pt'; // Portuguese as default
    this.translations = translations;
    this.supportedLangs = ['pt', 'en', 'es'];
  }

  t(key) {
    const translation = this.translations[key];
    if (!translation) {
      console.warn(`Translation missing: ${key}`);
      return key;
    }
    return translation[this.currentLang] || translation['pt'] || translation['en'] || key;
  }

  setLanguage(lang) {
    if (!this.supportedLangs.includes(lang)) return;
    this.currentLang = lang;
    localStorage.setItem('gv_lang', lang);
    this.updatePage();
    this.updateLangButtons();
  }

  getCurrentLanguage() {
    return this.currentLang;
  }

  updatePage() {
    if (this.currentLang === 'pt') {
      // Restore original PT defaults saved from the HTML markup
      document.querySelectorAll('[data-i18n]').forEach(el => {
        if (el._ptText !== undefined) el.textContent = el._ptText;
      });
      document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
        if (el._ptPlaceholder !== undefined) el.placeholder = el._ptPlaceholder;
      });
      document.documentElement.lang = 'pt';
      return;
    }

    // For EN/ES: save PT defaults on first switch, then apply translations
    document.querySelectorAll('[data-i18n]').forEach(el => {
      if (el._ptText === undefined) el._ptText = el.textContent;
      const key = el.getAttribute('data-i18n');
      const translation = this.translations[key];
      if (!translation) return;
      const text = translation[this.currentLang] || translation['en'];
      if (text) el.textContent = text;
    });

    document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
      if (el._ptPlaceholder === undefined) el._ptPlaceholder = el.placeholder;
      const key = el.getAttribute('data-i18n-placeholder');
      const translation = this.translations[key];
      if (!translation) return;
      const text = translation[this.currentLang] || translation['en'];
      if (text) el.placeholder = text;
    });

    document.documentElement.lang = this.currentLang;
  }

  updateLangButtons() {
    document.querySelectorAll('.lang-btn').forEach(btn => {
      btn.classList.remove('active');
      if (btn.getAttribute('data-lang') === this.currentLang) {
        btn.classList.add('active');
      }
    });
  }

  init() {
    this.updatePage();
    this.updateLangButtons();
    
    // Add click handlers to language buttons
    document.querySelectorAll('.lang-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        this.setLanguage(btn.getAttribute('data-lang'));
      });
    });
  }
}

// Initialize and export
const i18n = new I18n();
document.addEventListener('DOMContentLoaded', () => i18n.init());

// Make available globally
window.i18n = i18n;
window.t = (key) => i18n.t(key);
